scripts/run_skill.py:
#!/usr/bin/env python3
"""Run a skill as an agent: declared inputs -> script/llm steps -> checked outputs.

    python3 scripts/run_skill.py presales/effort-estimator \
        --input wbs=./wbs.csv --input rates=./rates.csv --input client=Acme \
        --out ./runs/acme --provider dry

    python3 scripts/run_skill.py --list              # agent skills and their inputs
    python3 scripts/run_skill.py --explain <skill>   # input contract in plain words
    python3 scripts/run_skill.py --demo <skill>      # run it on its own fixtures

The skill argument is `domain/name` or a path to the skill dir / SKILL.md.
Reads `metadata.agent` from SKILL.md (see docs/AGENT-REBUILD-PLAN.md §2):
  inputs:  [{name, type, required, from, default, copy, flag}]
           type: csv|json|md|txt|file|sql|dir (must exist) · path (may not exist yet)
                 string|args|flag (no file check; args is shell-split; flag -> {flag} when truthy)
  run:     [{step, kind: script|llm, ...}]
           script: cmd (python3 -> this interpreter with -I; `{name}`/`{out}`/`{skill_dir}`
                   substituted; `[... {opt} ...]` groups dropped when an optional input is
                   missing), stdout (file to capture), expect_exit (list, default [0]),
                   skip_if_missing (inputs)
           llm:    template, context (files), out, skip_if_missing
           any:    skip_if_present (inputs) — skip the step when one of them was supplied
  outputs: [{path, checks: [...]}]  — vocabulary in scripts/check_output.py

Exit codes: 0 all checks pass · 1 a step or check failed · 2 required input missing
(`{out}/needs_input.json` names it; `--assume name=value` proceeds with a labeled
assumption) · 3 not an agent skill / bad arguments.
Stdlib only. API keys are read by the provider from the environment and never written.

In-process mode (`--inproc` or RUN_SKILL_INPROC=1): script steps run via runpy in this
interpreter instead of a subprocess (same argv, cwd, stdout/stderr capture, exit codes,
`stdout:` redirection and `expect_exit`). Needed where subprocess does not exist
(Pyodide in the browser); outputs are byte-identical (tests/test_run_skill_inproc.py).
`--provider none` runs no LLM: llm steps are skipped with a recorded reason and their
checks fail honestly. `--provider jsbridge` routes LLM calls to a host-registered callback.
"""
from __future__ import annotations

import argparse
import json
import os
import re
import shlex
import shutil
import sys
import time
from pathlib import Path

HERE = Path(__file__).resolve().parent
ROOT = HERE.parent
SKILLS = ROOT / "skills"
SHARED = ROOT / "shared"
sys.path.insert(0, str(HERE))
import check_output  # noqa: E402
import skillmeta  # noqa: E402

FILE_TYPES = {"csv", "json", "md", "txt", "file", "sql", "dir", "path"}
MUST_EXIST = FILE_TYPES - {"path"}
TOKEN_RE = re.compile(r"\{([A-Za-z_][A-Za-z0-9_]*)\}")
OPT_GROUP_RE = re.compile(r"\[([^\[\]]*\{[^\[\]]*)\]")
CONTEXT_LIMIT = 12 * 1024
VENDOR_CONTEXT_LIMIT = 32 * 1024  # wrapped upstream instructions are read whole (largest today ~16 KB)

LLM_INSTRUCTION = ("Fill this template using ONLY the context files. Copy every number exactly as it appears in "
                   "them; never calculate, re-round or derive new numbers (percentages, totals, splits, rates) — if a "
                   "value would need calculating, write the marker instead. Where the files do not say, write "
                   "`[TO BE BASELINED — owner: <role>]` naming the accountable role (e.g. Client PMO, Delivery lead, "
                   "Account owner) — never leave the owner blank. Use one marker per unknown fact; drop empty example "
                   "rows instead of filling them with markers. Return the completed file only.")


# ------------------------------------------------------------------ discovery

def resolve_skill_dir(arg: str) -> Path:
    p = Path(arg)
    if p.is_file() and p.name == "SKILL.md":
        return p.parent.resolve()
    if p.is_dir() and (p / "SKILL.md").is_file():
        return p.resolve()
    cand = SKILLS / arg
    if (cand / "SKILL.md").is_file():
        return cand.resolve()
    sys.exit(f"error: skill not found: {arg} (use domain/name or a path)")


def skill_key(skill_dir: Path) -> str:
    try:
        rel = skill_dir.relative_to(SKILLS)
        return "/".join(rel.parts[:2])
    except ValueError:
        return skill_dir.name


def agent_skills():
    for md in sorted(SKILLS.rglob("SKILL.md")):
        if len(md.relative_to(SKILLS).parts) != 3:
            continue
        s = skillmeta.load_skill(md)
        if skillmeta.agent_block(s):
            yield s


def describe_inputs(agent: dict) -> list[str]:
    lines = []
    for i in agent.get("inputs", []):
        req = "required" if i.get("required") else "optional"
        extra = f" (default: {i['default']})" if i.get("default") not in (None, "") else ""
        src = f" — {i['from']}" if i.get("from") else ""
        lines.append(f"  --input {i['name']}=<{i.get('type', 'string')}>  [{req}]{extra}{src}")
    return lines


def cmd_list() -> int:
    skills = list(agent_skills())
    print(f"{len(skills)} agent skills")
    for s in skills:
        a = skillmeta.agent_block(s)
        print(f"\n{skill_key(s['dir'])}  v{s['metadata'].get('version', '?')}  "
              f"({len(a.get('run', []))} steps, {len(a.get('outputs', []))} outputs)")
        print("\n".join(describe_inputs(a)))
    return 0


def demo_args(arg: str) -> list[str]:
    """Translate --demo <skill> into a normal run using the skill's own happy-path eval fixtures."""
    skill_dir = resolve_skill_dir(arg)
    ev = skill_dir / "evals" / "evals.json"
    cases = json.loads(ev.read_text(encoding="utf-8")).get("cases", []) if ev.exists() else []
    case = next((c for c in cases if c.get("inputs") and "happy" in str(c.get("id", ""))), None) \
        or next((c for c in cases if c.get("inputs")), None)
    if not case:
        sys.exit(f"error: {arg} has no eval case with inputs to demo")
    argv = [skill_key(skill_dir)]
    for k, v in (case.get("inputs") or {}).items():
        v = str(v)
        if v.startswith("evals/"):
            v = str(skill_dir / v)
        argv += ["--input", f"{k}={v}"]
    for k, v in (case.get("assume") or {}).items():
        argv += ["--assume", f"{k}={v}"]
    print(f"demo: {skill_key(skill_dir)} on eval case '{case.get('id')}'", file=sys.stderr)
    return argv


def cmd_explain(arg: str) -> int:
    s = skillmeta.load_skill(resolve_skill_dir(arg))
    a = skillmeta.agent_block(s)
    if not a:
        print(f"{s['name']}: not an agent skill yet (no metadata.agent)")
        return 3
    print(f"# {s['name']} — how to run\n")
    print(s["description"].strip() + "\n")
    print("Inputs:")
    print("\n".join(describe_inputs(a)))
    print("\nSteps:")
    for st in a.get("run", []):
        if st.get("kind") == "llm":
            print(f"  {st['step']}: fill {st.get('template')} from {st.get('context', [])} -> {st.get('out')}")
        else:
            print(f"  {st['step']}: {st.get('cmd')}" + (f"  (stdout -> {st['stdout']})" if st.get("stdout") else ""))
    print("\nOutputs and checks:")
    for o in a.get("outputs", []):
        print(f"  {o['path']}: {', '.join(str(c) for c in o.get('checks', []))}")
    print("\nMissing a required input? The runner exits 2 and writes needs_input.json. "
          "Use --assume name=value to proceed with a labeled assumption.")
    return 0


# ------------------------------------------------------------------ inputs

def parse_kv(items, label):
    out = {}
    for it in items or []:
        if "=" not in it:
            sys.exit(f"error: {label} expects name=value, got {it!r}")
        k, _, v = it.partition("=")
        out[k.strip()] = v
    return out


def resolve_inputs(agent, given: dict, assumed: dict, out_dir: Path, skill_dir: Path):
    """Return (values, assumptions, missing). values[name] is '' for absent optional inputs."""
    values, assumptions, missing = {}, {}, []
    declared = agent.get("inputs", [])
    names = {i["name"] for i in declared}
    for k in list(given) + list(assumed):
        if k not in names:
            sys.exit(f"error: unknown input '{k}'; declared inputs: {sorted(names)}")
    for spec in declared:
        name, typ = spec["name"], str(spec.get("type", "string"))
        raw = None
        if name in given:
            raw = given[name]
        elif name in assumed:
            raw = assumed[name]
            assumptions[name] = f"[ASSUMED: {name} = {assumed[name]}]"
        elif spec.get("default") not in (None, ""):
            raw = str(spec["default"])
            if typ in FILE_TYPES and not Path(raw).is_absolute():
                raw = str(skill_dir / raw)
        if raw is None or raw == "":
            if spec.get("required"):
                missing.append({"name": name, "type": typ, "from": spec.get("from", ""),
                                "question": f"Provide `{name}` ({typ}): {spec.get('from', '')}".strip()})
            values[name] = ""
            continue
        raw = raw.replace("{out}", str(out_dir)).replace("{skill_dir}", str(skill_dir))
        if typ in FILE_TYPES:
            p = Path(raw).expanduser()
            if not p.is_absolute():
                p = (Path.cwd() / p).resolve()
            if typ in MUST_EXIST and not p.exists():
                missing.append({"name": name, "type": typ, "from": spec.get("from", ""),
                                "question": f"`{name}` file not found: {p}"})
                values[name] = ""
                continue
            if spec.get("copy") and p.is_file():
                out_dir.mkdir(parents=True, exist_ok=True)
                dest = out_dir / p.name
                if dest.resolve() != p.resolve():
                    shutil.copy(p, dest)
                p = dest
            values[name] = str(p)
        elif typ == "flag":
            truthy = str(raw).strip().lower() in ("1", "true", "yes", "y", "on")
            values[name] = str(spec.get("flag", f"--{name.replace('_', '-')}")) if truthy else ""
        else:
            values[name] = str(raw)
    return values, assumptions, missing


# ------------------------------------------------------------------ substitution

def substitute(text: str, values: dict) -> str:
    def rep(m):
        return values.get(m.group(1), m.group(0))
    return TOKEN_RE.sub(rep, text)


def build_argv(cmd: str, values: dict, arg_types: dict) -> list[str]:
    """Tokenize the template first, then substitute, so paths with spaces stay one argument."""
    # drop optional groups whose inputs are all missing
    def drop(m):
        group = m.group(1)
        refs = TOKEN_RE.findall(group)
        if refs and any(values.get(r, "") == "" for r in refs):
            return ""
        return group
    cmd = OPT_GROUP_RE.sub(drop, cmd)
    argv = []
    for tok in shlex.split(cmd):
        m = TOKEN_RE.fullmatch(tok)
        if m and arg_types.get(m.group(1)) == "args":
            argv += shlex.split(values.get(m.group(1), ""))
        else:
            sub = substitute(tok, values)
            if sub != "" or not m:
                argv.append(sub)
    return check_output.python_argv(argv)


# ------------------------------------------------------------------ steps

def run_script_step(step, values, arg_types, skill_dir: Path, logs: Path) -> dict:
    argv = build_argv(str(step.get("cmd", "")), values, arg_types)
    t0 = time.time()
    try:
        code, out, err = check_output.run_command(argv, cwd=skill_dir, timeout=900)
    except Exception as e:  # noqa: BLE001
        code, out, err = 127, "", f"could not run: {e}"
    dur = round(time.time() - t0, 3)
    name = str(step["step"])
    (logs / f"{name}.stdout.txt").write_text(out, encoding="utf-8")
    (logs / f"{name}.stderr.txt").write_text(err, encoding="utf-8")
    expect = step.get("expect_exit", [0])
    expect = [int(x) for x in (expect if isinstance(expect, list) else [expect])]
    ok = code in expect
    if step.get("stdout") and (ok or out.strip()):
        dest = Path(substitute(str(step["stdout"]), values))
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_text(out, encoding="utf-8")
    return {"step": name, "kind": "script", "cmd": " ".join(shlex.quote(a) for a in argv),
            "exit": code, "expected_exit": expect, "ok": ok, "duration_s": dur,
            "log": str(logs / f"{name}.stderr.txt"),
            "error": "" if ok else (err.strip().splitlines() or [f"exit {code}"])[-1][:300]}


def run_llm_step(step, values, assumptions, skill_dir: Path, provider, logs: Path) -> dict:
    name = str(step["step"])
    template = skill_dir / str(step.get("template", ""))
    out_path = Path(substitute(str(step.get("out", "")), values))
    if not template.is_file():
        return {"step": name, "kind": "llm", "ok": False, "exit": 1, "duration_s": 0,
                "error": f"template missing: {template}"}
    out_path.parent.mkdir(parents=True, exist_ok=True)
    t0 = time.time()
    tmpl = template.read_text(encoding="utf-8")
    if provider.name == "dry":
        out_path.write_text(tmpl.rstrip("\n") + "\n<!-- dry-run: template unfilled -->\n", encoding="utf-8")
        return {"step": name, "kind": "llm", "ok": True, "exit": 0, "provider": "dry",
                "duration_s": round(time.time() - t0, 3), "out": str(out_path), "error": ""}
    system = ((SHARED / "quality-bar.md").read_text(encoding="utf-8") + "\n\n"
              + (SHARED / "writing-style.md").read_text(encoding="utf-8"))
    parts = [LLM_INSTRUCTION, f"Today's date (use it for dates in the header): {time.strftime('%Y-%m-%d')}.", "", "## Template", "", tmpl]
    if assumptions:
        parts += ["", "## Assumptions supplied by the user (label each use as [ASSUMED: …])", ""]
        parts += [f"- {v}" for v in assumptions.values()]
    for ctx in step.get("context", []) or []:
        cp = Path(substitute(str(ctx), values))
        if not cp.is_absolute():
            cp = skill_dir / cp
        if not cp.is_file():
            parts += ["", f"## Context: {cp.name}", "", "(file missing)"]
            continue
        body = cp.read_text(encoding="utf-8", errors="replace")
        limit = VENDOR_CONTEXT_LIMIT if "/vendor/" in cp.as_posix() else CONTEXT_LIMIT
        if len(body) > limit:
            body = body[:limit] + f"\n[... truncated at {limit // 1024} KB ...]"
        parts += ["", f"## Context: {cp.name}", "", body]
    user = "\n".join(parts)
    (logs / f"{name}.prompt.txt").write_text(user, encoding="utf-8")
    try:
        text = provider.complete(system, user, temperature=0.2, max_tokens=4000)
    except Exception as e:  # noqa: BLE001
        if "no provider key" in str(e):
            # --provider none, or jsbridge with no callback registered: the step did not run.
            # Its output is absent, so the checks on it fail honestly.
            reason = "no provider key (LLM step not run)"
            return {"step": name, "kind": "llm", "ok": False, "exit": 1, "provider": provider.name,
                    "skipped": True, "skipped_reason": reason, "reason": reason,
                    "duration_s": round(time.time() - t0, 3), "error": f"skipped: {reason}"}
        return {"step": name, "kind": "llm", "ok": False, "exit": 1,
                "duration_s": round(time.time() - t0, 3), "error": f"provider error: {e}"[:300]}
    text = re.sub(r"^```[a-z]*\n|\n```\s*$", "", text.strip())
    out_path.write_text(text.rstrip("\n") + "\n", encoding="utf-8")
    return {"step": name, "kind": "llm", "ok": True, "exit": 0, "provider": provider.name,
            "duration_s": round(time.time() - t0, 3), "out": str(out_path), "error": ""}


# ------------------------------------------------------------------ main

def build_args():
    ap = argparse.ArgumentParser(description="Run a skill as an agent (inputs -> steps -> checked outputs)")
    ap.add_argument("skill", nargs="?", help="domain/name or path")
    ap.add_argument("--input", action="append", default=[], metavar="NAME=VALUE")
    ap.add_argument("--assume", action="append", default=[], metavar="NAME=VALUE",
                    help="supply a missing input as a labeled assumption")
    ap.add_argument("--out", default="", help="output dir (default: runs/<skill>-<timestamp>)")
    ap.add_argument("--provider", default="dry", choices=["dry", "anthropic", "openai", "jsbridge", "none"],
                    help="none = run no LLM: llm steps are skipped with a reason; jsbridge = host callback")
    ap.add_argument("--model", default="claude-sonnet-4-5")
    ap.add_argument("--inproc", action="store_true",
                    help="run script steps in this interpreter (runpy) instead of a subprocess")
    ap.add_argument("--list", action="store_true", help="list agent skills and their inputs")
    ap.add_argument("--explain", metavar="SKILL", help="print the input contract in plain words")
    ap.add_argument("--demo", metavar="SKILL", help="run the skill on its own happy-path eval fixtures")
    ap.add_argument("--reproduce", metavar="RUN_DIR",
                    help="audit a finished run: re-run its script steps on the recorded inputs and require every "
                         "declared output to be byte-identical (exit 0 identical, 1 differs, 3 not reproducible)")
    argv = sys.argv[1:]
    if "--demo" in argv:
        i = argv.index("--demo")
        argv = demo_args(argv[i + 1]) + argv[:i] + argv[i + 2:]
    return ap.parse_args(argv)


def cmd_reproduce(run_dir_arg: str) -> int:
    """Integrity audit: the delivered files are exactly what the skill's code computes from the recorded inputs.
    (Correctness of the code itself is proven by its unit tests and tests/test_differential.py.)"""
    import subprocess  # CLI-only audit (never used in the in-process runtime)
    import tempfile
    run_dir = Path(run_dir_arg).expanduser().resolve()
    rj = run_dir / "run.json"
    if not rj.is_file():
        print(f"error: {rj} not found", file=sys.stderr)
        return 3
    run = json.loads(rj.read_text(encoding="utf-8"))
    skill_dir = resolve_skill_dir(run["skill"])
    agent = skillmeta.agent_block(skillmeta.load_skill(skill_dir)) or {}
    if any(st.get("kind", "script") == "llm" for st in agent.get("run") or []):
        print(f"{run['skill']}: not reproducible — it has a model step (model text is not deterministic)")
        return 3
    types = {i["name"]: i.get("type", "string") for i in agent.get("inputs") or []}
    argv = [sys.executable, str(Path(__file__).resolve()), run["skill"], "--provider", "none"]
    for k, v in sorted((run.get("inputs") or {}).items()):
        if types.get(k) == "flag":
            if v:
                argv += ["--input", f"{k}=true"]
        elif v not in (None, ""):
            argv += ["--input", f"{k}={v}"]
    with tempfile.TemporaryDirectory() as tmp:
        subprocess.run(argv + ["--out", tmp], capture_output=True, text=True, cwd=str(ROOT))
        diffs, same = [], 0
        for o in agent.get("outputs") or []:
            rel = str(o.get("path", "")).replace("{out}/", "")
            a, b = run_dir / rel, Path(tmp) / rel
            if not a.is_file() and not b.is_file():
                continue
            # the run's own output folder path may appear in a file (e.g. a log line); it is not content
            norm = lambda f, d: f.read_bytes().replace(str(d).encode(), b"<OUT>")  # noqa: E731
            if not a.is_file() or not b.is_file() or norm(a, run_dir) != norm(b, Path(tmp)):
                diffs.append(rel)
            else:
                same += 1
    if diffs:
        print(f"{run['skill']}: NOT REPRODUCED — differs from a fresh run on the recorded inputs: {', '.join(diffs)}")
        return 1
    print(f"{run['skill']}: reproduced — {same} output file(s) byte-identical to a fresh run on the recorded inputs")
    return 0


def main() -> int:
    args = build_args()
    if args.reproduce:
        return cmd_reproduce(args.reproduce)
    if args.list:
        return cmd_list()
    if args.explain:
        return cmd_explain(args.explain)
    if not args.skill:
        sys.exit("error: give a skill (domain/name), --list or --explain")
    if args.inproc:
        os.environ["RUN_SKILL_INPROC"] = "1"

    skill_dir = resolve_skill_dir(args.skill)
    skill = skillmeta.load_skill(skill_dir)
    agent = skillmeta.agent_block(skill)
    if not agent:
        print(f"error: {skill['name']} is not an agent skill yet (no metadata.agent in SKILL.md)",
              file=sys.stderr)
        return 3
    out_dir = Path(args.out) if args.out else ROOT / "runs" / f"{skill['name']}-{int(time.time())}"
    out_dir = out_dir.expanduser().resolve()
    out_dir.mkdir(parents=True, exist_ok=True)
    logs = out_dir / "logs"
    logs.mkdir(exist_ok=True)

    given = parse_kv(args.input, "--input")
    assumed = parse_kv(args.assume, "--assume")
    values, assumptions, missing = resolve_inputs(agent, given, assumed, out_dir, skill_dir)
    if missing:
        payload = {"skill": skill_key(skill_dir), "missing": missing,
                   "hint": "re-run with --input name=value, or --assume name=value to proceed with a labeled assumption"}
        (out_dir / "needs_input.json").write_text(json.dumps(payload, indent=2), encoding="utf-8")
        for m in missing:
            print(f"needs input: {m['question']}", file=sys.stderr)
        print(f"wrote {out_dir / 'needs_input.json'}", file=sys.stderr)
        return 2

    values["out"] = str(out_dir)
    values["skill_dir"] = str(skill_dir)
    arg_types = {i["name"]: str(i.get("type", "string")) for i in agent.get("inputs", [])}

    sys.path.insert(0, str(HERE))
    from behavioral_evals import make_provider  # noqa: E402  (reuses the provider abstraction)
    provider = make_provider(args.provider, args.model)

    steps, halted = [], False
    for step in agent.get("run", []):
        skip = [s for s in (step.get("skip_if_missing") or []) if values.get(str(s), "") == ""]
        present = [s for s in (step.get("skip_if_present") or []) if values.get(str(s), "") != ""]
        if skip or present:
            reason = (f"missing optional input(s): {skip}" if skip else f"input(s) supplied: {present}")
            steps.append({"step": str(step["step"]), "kind": step.get("kind"), "ok": True,
                          "skipped": True, "reason": reason})
            continue
        if halted:
            steps.append({"step": str(step["step"]), "kind": step.get("kind"), "ok": False,
                          "skipped": True, "reason": "earlier step failed"})
            continue
        if step.get("kind") == "llm":
            res = run_llm_step(step, values, assumptions, skill_dir, provider, logs)
        else:
            res = run_script_step(step, values, arg_types, skill_dir, logs)
        steps.append(res)
        if not res["ok"]:
            halted = True

    mode = "dry" if args.provider == "dry" else "real"
    checks = []
    for o in agent.get("outputs", []):
        path = substitute(str(o.get("path", "")), values)
        for c in o.get("checks", []) or []:
            spec = substitute(str(c), values)
            r = check_output.run_check(spec, path, mode=mode, out_dir=str(out_dir), cwd=str(skill_dir))
            r["path"] = path
            checks.append(r)

    ok = all(s["ok"] for s in steps) and all(c["pass"] for c in checks)
    run = {"skill": skill_key(skill_dir), "version": str(skill["metadata"].get("version", "")),
           "provider": args.provider, "model": args.model if args.provider in ("anthropic", "openai", "jsbridge") else "",
           "out": str(out_dir),
           "inputs": {k: v for k, v in values.items() if k not in ("out", "skill_dir")},
           "assumptions": assumptions, "steps": steps, "checks": checks, "ok": ok}
    (out_dir / "run.json").write_text(json.dumps(run, indent=2), encoding="utf-8")
    n_pass = sum(c["pass"] for c in checks)
    print(f"{run['skill']}: {'OK' if ok else 'FAILED'} — {len(steps)} steps, "
          f"{n_pass}/{len(checks)} checks passed; see {out_dir / 'run.json'}")
    for s in steps:
        if not s["ok"]:
            print(f"  step {s['step']} failed: {s.get('error') or s.get('reason')}")
    for c in checks:
        if not c["pass"]:
            print(f"  check {c['check']} on {Path(c['path']).name}: {c['evidence']}")
    return 0 if ok else 1


if __name__ == "__main__":
    try:
        sys.exit(main())
    except BrokenPipeError:  # e.g. `--list | head`
        sys.exit(0)

scripts/check_output.py:
#!/usr/bin/env python3
"""Output checks for skill runs — one fixed vocabulary, implemented once.

Check spec syntax (a string):
  exists                       file exists and is non-empty
  json                         file parses as JSON
  csv:[a,b]                    CSV header contains every listed column
  csv_rows:<col>!empty         every row has a non-empty <col>
  csv_rows:<col>~<regex>       every row's <col> matches <regex> (re.search); the column must exist
                               and the CSV must have >= 1 data row. Dry mode: a column that is
                               blank in every row is an unfilled llm slot and is skipped
  yaml                       file is non-empty and parses with the repo's YAML subset
  sections:[A,B]               a Markdown heading contains each listed text (case-insensitive)
  no_unowned_tbd               every `[TO BE BASELINED` marker names an owner (real mode);
                               dry mode only verifies the marker format `— owner:`
  numbers_trace_to:<file>      every number (ISO dates excluded) in the output with >= 3 significant digits, or
                               with a $ or % sign, appears in <file> (list of files allowed);
                               skipped in dry mode
  cites_source_ids:<file>      every `[Sn]` citation in the output exists as an id `Sn` in <file>;
                               skipped in dry mode
  mermaid_parses               every ```mermaid block has balanced brackets and >= 1 edge
  max_lines:N                  output has at most N lines
  contains:"text"              output contains the literal text
  cmd:"..."                    run the command (python3 -> this interpreter, `{path}` substituted);
                               expect exit 0
  exit:N                       run-level: the process exit code equals N
  needs_input:<name>           run-level: needs_input.json in the out dir names <name>

Programmatic:
    run_check(spec, path=None, *, mode="dry", exit_code=None, out_dir=None, cwd=None) -> dict
    returns {"check": spec, "pass": bool, "evidence": str}
CLI:
    python3 scripts/check_output.py <file> <check> [<check> ...] [--mode dry|real]
Exit 0 when every check passes, 1 otherwise. Stdlib only.
"""
from __future__ import annotations

import argparse
import contextlib
import csv
import io
import json
import os
import re
import runpy
import shlex
import subprocess
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import skillmeta  # noqa: E402


# ------------------------------------------------------------------ command execution
# One executor for run_skill.py script steps and `cmd:` checks. Subprocess by default;
# in-process (runpy) when RUN_SKILL_INPROC=1 or inproc=True — the only path available
# where subprocess does not exist (Pyodide). Same argv, cwd, captured stdout/stderr and
# exit code either way, so outputs are byte-identical.

def inproc_enabled() -> bool:
    return os.environ.get("RUN_SKILL_INPROC") == "1"


def subprocess_available() -> bool:
    """False on Pyodide/Emscripten (no fork/exec) or when RUN_SKILL_NO_SUBPROCESS=1 (tests)."""
    return sys.platform != "emscripten" and os.environ.get("RUN_SKILL_NO_SUBPROCESS") != "1"


def python_argv(tokens: list[str]) -> list[str]:
    """`python3 ...` -> this interpreter in isolated mode (dedupes a leading -I)."""
    if tokens and tokens[0] in ("python3", "python"):
        return [sys.executable or "python3", "-I"] + [t for t in tokens[1:] if t != "-I"]
    return tokens


def _script_argv(argv: list[str]):
    """argv for the script itself when argv is `<python> [-I] <file.py> ...`, else None."""
    if not argv or argv[0] not in (sys.executable or "python3", "python3", "python"):
        return None
    rest = [a for a in argv[1:] if a != "-I"]
    if not rest or not rest[0].endswith(".py"):
        return None  # `-m module`, `-c`, or a non-python command
    return rest


class _Exit(SystemExit):
    pass


def run_inproc(script_argv: list[str], cwd) -> tuple[int, str, str]:
    """Run `script_argv[0]` as __main__ with sys.argv=script_argv, like a fresh `python -I`.

    Returns (exit_code, stdout, stderr). SystemExit follows the interpreter's rules:
    None/0 -> 0, int -> that code, anything else -> printed to stderr, exit 1.
    Uncaught exceptions print a traceback to stderr and exit 1. sys.path[0], cwd and
    the modules the script imported are restored/removed afterwards.
    """
    script = Path(script_argv[0])
    if cwd and not script.is_absolute():
        script = Path(cwd) / script
    script = script.resolve()
    out, err = io.StringIO(), io.StringIO()
    saved_argv, saved_path, saved_cwd = sys.argv, list(sys.path), os.getcwd()
    saved_modules = set(sys.modules)
    code = 0
    try:
        if cwd:
            os.chdir(str(cwd))
        sys.argv = list(script_argv)
        sys.path.insert(0, str(script.parent))
        with contextlib.redirect_stdout(out), contextlib.redirect_stderr(err):
            try:
                runpy.run_path(str(script), run_name="__main__")
            except SystemExit as e:  # noqa: PERF203
                c = e.code
                if c is None:
                    code = 0
                elif isinstance(c, int):
                    code = c
                else:
                    print(c, file=sys.stderr)
                    code = 1
            except BaseException:  # noqa: BLE001 — a crash is exit 1 with the traceback on stderr
                import traceback
                traceback.print_exc()
                code = 1
    finally:
        sys.argv, sys.path = saved_argv, saved_path
        os.chdir(saved_cwd)
        for m in set(sys.modules) - saved_modules:
            sys.modules.pop(m, None)
    return code, out.getvalue(), err.getvalue()


def run_command(argv: list[str], cwd=None, timeout: int = 900, inproc: bool | None = None) -> tuple[int, str, str]:
    """Run argv; (exit_code, stdout, stderr). In-process: a `python3 <file.py>` command runs via
    runpy; anything else falls back to a subprocess, or raises where none exists (Pyodide)."""
    if inproc is None:
        inproc = inproc_enabled()
    if inproc:
        sa = _script_argv(argv)
        if sa is not None:
            return run_inproc(sa, cwd)
        if not subprocess_available():
            raise RuntimeError("subprocess unavailable in-process (only `python3 <script.py> ...` can run)")
    r = subprocess.run(argv, capture_output=True, text=True, cwd=str(cwd) if cwd else None, timeout=timeout)
    return r.returncode, r.stdout, r.stderr

VOCAB = {
    "exists", "json", "csv", "csv_rows", "yaml", "sections", "no_unowned_tbd", "numbers_trace_to",
    "cites_source_ids", "mermaid_parses", "max_lines", "contains", "cmd", "exit", "needs_input",
}
RUN_LEVEL = {"exit", "needs_input"}

TBD_RE = re.compile(r"\[TO BE BASELINED[^\]]*\]")
NUMBER_RE = re.compile(r"(?<![\w.])([$€£]?)(-?\d[\d,]*(?:\.\d+)?)(%?)(?![\w])")
CITE_RE = re.compile(r"\[(S\d+)\]")


def parse_spec(spec: str):
    """Split 'name:arg' into (name, arg). arg is a str, list or None."""
    spec = str(spec).strip()
    if ":" not in spec:
        return spec, None
    name, _, arg = spec.partition(":")
    arg = arg.strip()
    if arg.startswith("["):
        arg = skillmeta.parse_flow(arg)
        if not isinstance(arg, list):
            arg = [arg]
        arg = [str(a) for a in arg]
    else:
        arg = str(skillmeta.scalar(arg))
    return name.strip(), arg


def _result(spec, ok, evidence):
    return {"check": str(spec), "pass": bool(ok), "evidence": str(evidence)[:300]}


def _read(path: Path) -> str:
    return path.read_text(encoding="utf-8", errors="replace")


def _sig_digits(num: str) -> int:
    digits = num.replace(",", "").replace("-", "").replace(".", "").lstrip("0")
    return len(digits)


ISO_DATE_RE = re.compile(r"\b\d{4}-\d{2}-\d{2}\b")


def _numbers(text: str):
    """Numbers worth tracing: >=3 significant digits or carrying $ / %. ISO dates (yyyy-mm-dd) are dates, not figures."""
    out = []
    for m in NUMBER_RE.finditer(ISO_DATE_RE.sub(" ", text)):
        sym, num, pct = m.groups()
        if sym or pct or _sig_digits(num) >= 3:
            out.append(num.replace(",", ""))
    return out


def _all_numbers(text: str):
    return [m.group(2).replace(",", "") for m in NUMBER_RE.finditer(text)]


def _number_in(num: str, ref_numbers: list[str]) -> bool:
    if num in ref_numbers:
        return True
    try:
        n = float(num)
    except ValueError:
        return False
    decimals = len(num.split(".")[1]) if "." in num else 0
    tol = 0.5 * 10 ** (-decimals)
    for r in ref_numbers:
        try:
            rv = float(r)
        except ValueError:
            continue
        if abs(rv - n) <= tol + 1e-9:
            return True
    return False


def _resolve(ref, cwd):
    p = Path(str(ref))
    if not p.is_absolute() and cwd:
        p = Path(cwd) / p
    return p


def _csv_rows(spec, arg: str, text: str, mode: str) -> dict:
    """csv_rows:<col>!empty | csv_rows:<col>~<regex> — a per-row predicate on one column."""
    arg = arg.strip()
    if arg.endswith("!empty"):
        col, pred, pattern = arg[: -len("!empty")].strip(), "!empty", None
    elif "~" in arg:
        col, _, pattern = arg.partition("~")
        col, pred = col.strip(), "~"
        try:
            rx = re.compile(pattern)
        except re.error as e:
            return _result(spec, False, f"bad regex {pattern!r}: {e}")
    else:
        return _result(spec, False, f"csv_rows needs '<col>!empty' or '<col>~<regex>', got {arg!r}")
    if not col:
        return _result(spec, False, "csv_rows: empty column name")
    rows = list(csv.DictReader(io.StringIO(text)))
    header = rows[0].keys() if rows else next(csv.reader(io.StringIO(text)), [])
    if col not in header:
        return _result(spec, False, f"column '{col}' not in header {list(header)}")
    if not rows:
        return _result(spec, False, "no data rows")
    values = [(r.get(col) or "").strip() for r in rows]
    if mode == "dry" and all(v == "" for v in values):
        return _result(spec, True, f"skipped in dry mode: '{col}' unfilled in all {len(rows)} rows")
    if pred == "!empty":
        bad = [i + 2 for i, v in enumerate(values) if v == ""]
        label = "empty"
    else:
        bad = [i + 2 for i, v in enumerate(values) if not rx.search(v)]
        label = f"not matching {pattern!r}"
    return _result(spec, not bad, f"{len(bad)} of {len(rows)} rows {label} in '{col}'"
                   + (f" (lines {bad[:6]})" if bad else ""))


# ------------------------------------------------------------------ checks

def run_check(spec, path=None, *, mode: str = "dry", exit_code=None, out_dir=None, cwd=None) -> dict:
    name, arg = parse_spec(spec)
    if name not in VOCAB:
        return _result(spec, False, f"unknown check '{name}'")

    # ---- run-level checks
    if name == "exit":
        want = int(arg) if arg not in (None, "") else 0
        return _result(spec, exit_code == want, f"exit code {exit_code}, expected {want}")
    if name == "needs_input":
        f = Path(out_dir or ".") / "needs_input.json"
        if not f.exists():
            return _result(spec, False, "needs_input.json not written")
        try:
            data = json.loads(_read(f))
        except Exception as e:  # noqa: BLE001
            return _result(spec, False, f"needs_input.json invalid: {e}")
        names = [m.get("name") for m in data.get("missing", [])]
        return _result(spec, arg in names, f"missing inputs named: {names}")

    # ---- file-level checks
    if path is None:
        return _result(spec, False, "no file given")
    p = Path(path)
    if name == "exists":
        ok = p.is_file() and p.stat().st_size > 0
        return _result(spec, ok, f"{p} {'exists' if p.exists() else 'missing'}"
                       + ("" if ok or not p.exists() else " (empty)"))
    if name == "cmd":
        if not arg:
            return _result(spec, False, "cmd has no command")
        # the command runs in the skill dir (cwd), so the output path must be absolute, whatever --out was given as
        tokens = python_argv(shlex.split(str(arg).replace("{path}", str(Path(p).resolve()))))
        if inproc_enabled() and _script_argv(tokens) is None and not subprocess_available():
            return _result(spec, False, "skipped: subprocess unavailable in-process")
        try:
            code, out, err = run_command(tokens, cwd=cwd, timeout=600)
        except Exception as e:  # noqa: BLE001
            return _result(spec, False, f"could not run: {e}")
        tail = (out + err).strip().splitlines()[-1:] or [""]
        return _result(spec, code == 0, f"exit {code}: {tail[0]}")
    if not p.is_file():
        return _result(spec, False, f"{p} missing")
    text = _read(p)

    if name == "json":
        try:
            json.loads(text)
            return _result(spec, True, "valid JSON")
        except Exception as e:  # noqa: BLE001
            return _result(spec, False, f"invalid JSON: {e}")
    if name == "csv":
        try:
            header = next(csv.reader(io.StringIO(text)))
        except StopIteration:
            return _result(spec, False, "empty CSV")
        want = arg if isinstance(arg, list) else ([arg] if arg else [])
        missing = [c for c in want if c not in header]
        return _result(spec, not missing, f"missing columns {missing}" if missing else f"header has {want}")
    if name == "csv_rows":
        return _csv_rows(spec, str(arg or ""), text, mode)
    if name == "yaml":
        if not text.strip():
            return _result(spec, False, "empty file")
        try:
            data = skillmeta.parse_yaml_subset(text)
            return _result(spec, bool(data), f"parsed {len(data)} top-level keys")
        except Exception as e:  # noqa: BLE001
            return _result(spec, False, f"yaml subset parse failed: {e}")
    if name == "sections":
        heads = [ln.lstrip("#").strip().lower() for ln in text.splitlines() if ln.startswith("#")]
        want = arg if isinstance(arg, list) else ([arg] if arg else [])
        missing = [w for w in want if not any(w.lower() in h for h in heads)]
        return _result(spec, not missing, f"missing headings {missing}" if missing else f"found {want}")
    if name == "no_unowned_tbd":
        bad = []
        for m in TBD_RE.finditer(text):
            marker = m.group(0)
            om = re.search(r"owner:\s*([^\]]*)", marker)
            if mode == "dry":
                if om is None:
                    bad.append(marker)
            else:
                owner = om.group(1).strip() if om else ""
                if not owner or set(owner) <= set("_ "):
                    bad.append(marker)
        n = len(TBD_RE.findall(text))
        return _result(spec, not bad, f"{len(bad)} unowned of {n} markers" + (f": {bad[0]}" if bad else ""))
    if name == "numbers_trace_to":
        if mode == "dry":
            return _result(spec, True, "skipped in dry mode")
        refs = arg if isinstance(arg, list) else [arg]
        ref_nums = []
        for ref in refs:
            rp = _resolve(ref, cwd)
            if not rp.is_file():
                return _result(spec, False, f"reference file missing: {rp}")
            raw = _read(rp)
            if rp.suffix.lower() == ".csv":  # read cells: "12,34" across two cells is two numbers, not 1234
                import csv as _csv
                import io as _io
                ref_nums += [n for row in _csv.reader(_io.StringIO(raw)) for cell in row for n in _all_numbers(cell)]
            else:
                ref_nums += _all_numbers(raw)
        missing = sorted({n for n in _numbers(text) if not _number_in(n, ref_nums)})
        return _result(spec, not missing, f"untraced numbers {missing[:8]}" if missing
                       else f"all {len(_numbers(text))} numbers trace")
    if name == "cites_source_ids":
        if mode == "dry":
            return _result(spec, True, "skipped in dry mode")
        rp = _resolve(arg, cwd)
        if not rp.is_file():
            return _result(spec, False, f"reference file missing: {rp}")
        ids = set(re.findall(r"\bS\d+\b", _read(rp)))
        cited = set(CITE_RE.findall(text))
        missing = sorted(cited - ids)
        return _result(spec, not missing and bool(cited),
                       f"unknown source ids {missing}" if missing
                       else (f"{len(cited)} citations resolve" if cited else "no [Sn] citations found"))
    if name == "mermaid_parses":
        blocks = re.findall(r"```mermaid\s*\n(.*?)```", text, re.S)
        if not blocks:
            return _result(spec, False, "no mermaid block")
        er_edge = re.compile(r"[|}o][|o]?(--|\.\.)[|o]?[|{o]")  # erDiagram cardinality, e.g. ||--o{  }|..|{
        for b in blocks:
            is_er = b.lstrip().startswith("erDiagram")
            # erDiagram uses { } for cardinality markers and attribute blocks, so only () [] must balance there
            for o, c in (("[]", "()") if is_er else ("[]", "{}", "()")):
                if b.count(o) != b.count(c):
                    return _result(spec, False, f"unbalanced {o}{c}")
            if "-->" not in b and "---" not in b and "->>" not in b and not (is_er and er_edge.search(b)):
                return _result(spec, False, "no edges")
        return _result(spec, True, f"{len(blocks)} block(s) ok")
    if name == "max_lines":
        n = text.count("\n") + (0 if text.endswith("\n") or not text else 1)
        limit = int(arg)
        return _result(spec, n <= limit, f"{n} lines (max {limit})")
    if name == "contains":
        needle = str(arg)
        return _result(spec, needle in text, f"{'found' if needle in text else 'missing'}: {needle}")
    return _result(spec, False, "unhandled")


def run_checks(specs, path=None, **kw) -> list[dict]:
    return [run_check(s, path, **kw) for s in specs]


def main() -> int:
    ap = argparse.ArgumentParser(description="Run output checks on a file")
    ap.add_argument("file")
    ap.add_argument("checks", nargs="+")
    ap.add_argument("--mode", choices=["dry", "real"], default="real")
    ap.add_argument("--json", action="store_true")
    a = ap.parse_args()
    results = run_checks(a.checks, a.file, mode=a.mode, cwd=str(Path.cwd()))
    if a.json:
        print(json.dumps(results, indent=2))
    else:
        for r in results:
            print(f"{'PASS' if r['pass'] else 'FAIL'}  {r['check']}  — {r['evidence']}")
    return 0 if all(r["pass"] for r in results) else 1


if __name__ == "__main__":
    sys.exit(main())

