import argparse
import json
import re
import sys
from pathlib import Path

NAME_RE = re.compile(r"^[a-z][a-z0-9_]*$")
ALIAS = {"inputSchema": ("inputSchema", "input_schema"), "outputSchema": ("outputSchema", "output_schema")}

