// app/api/health/deep/route.ts — readiness. Checks each dependency with a timeout. Bearer-protected.
import "server-only";
import { NextResponse, type NextRequest } from "next/server";
import { log } from "@/lib/logger";
import { createAdminClient } from "@/lib/supabase/admin"; // rls-lint: allow — health check only, read-only

export const dynamic = "force-dynamic";
export const runtime = "nodejs";

type CheckStatus = "ok" | "degraded" | "down";
type Check = { status: CheckStatus; latencyMs: number; error?: string; detail?: string };

const TIMEOUT_MS = 3000;
const SLOW_MS = 1500;
const REQUIRED = new Set(["db", "auth"]);

async function withTimeout<T>(p: Promise<T>, ms = TIMEOUT_MS): Promise<T> {
  let t: ReturnType<typeof setTimeout> | undefined;
  const timeout = new Promise<never>((_, rej) => { t = setTimeout(() => rej(new Error("timeout")), ms); });
  try { return await Promise.race([p, timeout]); } finally { clearTimeout(t); }
}

async function run(name: string, fn: () => Promise<void>): Promise<[string, Check]> {
  const started = Date.now();
  try {
    await withTimeout(fn());
    const latencyMs = Date.now() - started;
    return [name, { status: latencyMs > SLOW_MS ? "degraded" : "ok", latencyMs, ...(latencyMs > SLOW_MS ? { detail: "slow" } : {}) }];
  } catch (e) {
    return [name, { status: "down", latencyMs: Date.now() - started, error: e instanceof Error ? e.message : String(e) }];
  }
}

export async function GET(req: NextRequest) {
  const token = process.env.HEALTH_CHECK_TOKEN;
  if (token && req.headers.get("authorization") !== `Bearer ${token}`) {
    return NextResponse.json({ error: { code: "AUTH_REQUIRED", message: "unauthorized" } }, { status: 401 });
  }
  const simulate = process.env.VERCEL_ENV !== "production" ? req.nextUrl.searchParams.get("simulate") : null;

  const admin = createAdminClient();
  const checks = Object.fromEntries(
    await Promise.all([
      run("db", async () => {
        if (simulate === "error") throw new Error("simulated");
        if (simulate === "slow") await new Promise((r) => setTimeout(r, SLOW_MS + 100));
        const { error } = await admin.rpc("health_ping"); // `create function app.health_ping() returns int language sql as $$ select 1 $$;`
        if (error) throw new Error(error.message);
      }),
      run("auth", async () => {
        const res = await fetch(`${process.env.NEXT_PUBLIC_SUPABASE_URL}/auth/v1/health`, { cache: "no-store" });
        if (!res.ok) throw new Error(`auth ${res.status}`);
      }),
      run("storage", async () => {
        const { error } = await admin.storage.listBuckets();
        if (error) throw new Error(error.message);
      }),
    ]),
  ) as Record<string, Check>;

  const required = Object.entries(checks).filter(([n]) => REQUIRED.has(n));
  const status: CheckStatus = required.some(([, c]) => c.status === "down")
    ? "down"
    : Object.values(checks).some((c) => c.status !== "ok") ? "degraded" : "ok";

  if (status !== "ok") log[status === "down" ? "error" : "warn"]({ action: "health.deep", checks }, "health check not ok");

  return NextResponse.json(
    { status, version: process.env.VERCEL_GIT_COMMIT_SHA?.slice(0, 7) ?? "local", env: process.env.VERCEL_ENV ?? "development", ts: new Date().toISOString(), checks },
    { status: status === "down" ? 503 : 200, headers: { "Cache-Control": "no-store" } },
  );
}

// app/api/health/route.ts — liveness. No dependencies. Never cached.
import { NextResponse } from "next/server";

export const dynamic = "force-dynamic";
export const runtime = "nodejs";

export function GET() {
  return NextResponse.json(
    {
      status: "ok",
      version: process.env.VERCEL_GIT_COMMIT_SHA?.slice(0, 7) ?? "local",
      env: process.env.VERCEL_ENV ?? process.env.NODE_ENV ?? "development",
      ts: new Date().toISOString(),
    },
    { headers: { "Cache-Control": "no-store" } },
  );
}

// lib/logger/context.ts — request-scoped context via AsyncLocalStorage (node runtime).
import { AsyncLocalStorage } from "node:async_hooks";

export type LogContext = {
  requestId?: string;
  vercelId?: string;
  userId?: string;
  tenantId?: string;
  route?: string;
};

const als = new AsyncLocalStorage<LogContext>();

export function getLogContext(): LogContext {
  return als.getStore() ?? {};
}

/** Run fn with a fresh context (call at the top of a route handler / action / job). */
export function withLogContext<T>(ctx: LogContext, fn: () => T): T {
  return als.run({ ...getLogContext(), ...ctx }, fn);
}

/** Enrich the current context (e.g. after requireUser()). No-op outside a context. */
export function enrichLogContext(patch: Partial<LogContext>): void {
  const store = als.getStore();
  if (store) Object.assign(store, patch);
}

/** Derive ids from incoming headers (used by middleware and route handlers). */
export function contextFromHeaders(h: Headers, route?: string): LogContext {
  return {
    requestId: h.get("x-request-id") ?? crypto.randomUUID(),
    vercelId: h.get("x-vercel-id") ?? undefined,
    route,
  };
}

// lib/logger.ts — structured JSON logger with redaction and request context. No deps.
import { getLogContext } from "./logger/context";

type Level = "debug" | "info" | "warn" | "error";
const LEVELS: Record<Level, number> = { debug: 10, info: 20, warn: 30, error: 40 };

const REDACT_KEYS = /^(password|passwd|secret|token|authorization|cookie|set-cookie|apikey|api_key|key|email|phone|ssn|card|iban|dsn)$/i;
const MAX_STR = 2048;
const MAX_DEPTH = 5;

const minLevel: number = LEVELS[(process.env.LOG_LEVEL as Level) ?? (process.env.NODE_ENV === "production" ? "info" : "debug")] ?? 20;
const pretty = process.env.NODE_ENV === "development" && process.env.LOG_PRETTY === "1";

const base = {
  service: process.env.SERVICE_NAME ?? "web",
  env: process.env.VERCEL_ENV ?? process.env.NODE_ENV ?? "development",
  version: process.env.VERCEL_GIT_COMMIT_SHA?.slice(0, 7) ?? "local",
};

export function redact(value: unknown, depth = 0): unknown {
  if (depth > MAX_DEPTH) return "[depth]";
  if (typeof value === "string") return value.length > MAX_STR ? `${value.slice(0, MAX_STR)}…[+${value.length - MAX_STR}]` : value;
  if (value instanceof Error) return serializeError(value);
  if (Array.isArray(value)) return value.map((v) => redact(v, depth + 1));
  if (value && typeof value === "object") {
    const out: Record<string, unknown> = {};
    for (const [k, v] of Object.entries(value as Record<string, unknown>)) {
      out[k] = REDACT_KEYS.test(k) ? "[redacted]" : redact(v, depth + 1);
    }
    return out;
  }
  return value;
}

export function serializeError(e: unknown): { name: string; message: string; code?: string; stack?: string } {
  if (e instanceof Error) {
    const code = (e as { code?: string }).code;
    // stack is always captured here; emit() drops it below `error` level
    return { name: e.name, message: e.message, ...(code ? { code } : {}), stack: e.stack };
  }
  return { name: "NonError", message: String(e) };
}

function emit(level: Level, ctx: Record<string, unknown> | undefined, msg: string) {
  if (LEVELS[level] < minLevel) return;
  const { err, ...rest } = ctx ?? {};
  const line = {
    ts: new Date().toISOString(),
    level,
    msg,
    ...base,
    ...getLogContext(),
    ...(redact(rest) as Record<string, unknown>),
    ...(err !== undefined ? { err: level === "error" ? serializeError(err) : { ...serializeError(err), stack: undefined } } : {}),
  };
  const out = pretty ? `${line.ts} ${level.toUpperCase().padEnd(5)} ${msg} ${JSON.stringify(rest)}` : JSON.stringify(line);
  // eslint-disable-next-line no-console
  (level === "error" ? console.error : level === "warn" ? console.warn : console.log)(out);
}

type LogFn = {
  (msg: string): void;
  (ctx: Record<string, unknown>, msg: string): void;
};
const make = (level: Level): LogFn => ((a: unknown, b?: string) => (typeof a === "string" ? emit(level, undefined, a) : emit(level, a as Record<string, unknown>, b ?? ""))) as LogFn;

export const log = {
  debug: make("debug"),
  info: make("info"),
  warn: make("warn"),
  error: make("error"),
  /** Time an operation and log its outcome once. */
  async time<T>(action: string, fn: () => Promise<T>, ctx: Record<string, unknown> = {}): Promise<T> {
    const started = Date.now();
    try {
      const v = await fn();
      emit("info", { ...ctx, action, outcome: "ok", durationMs: Date.now() - started }, "operation completed");
      return v;
    } catch (err) {
      emit("error", { ...ctx, action, outcome: "THREW", durationMs: Date.now() - started, err }, "operation failed");
      throw err;
    }
  },
};

