-- Migration: <YYYYMMDDHHMMSS>_<verb>_<object>
-- Purpose: <what and why; link SPEC § / plan file>
-- Depends on: <migration names>
-- Destructive: no | yes (expand/contract step N of 3)
-- Backfill: none | separate migration <name>

begin;

-- 1. Tables
create table public.<table> (
  id          uuid primary key default gen_random_uuid(),
  tenant_id   uuid not null references public.tenants(id) on delete cascade default app.tenant_id(),
  created_by  uuid not null references auth.users(id) default auth.uid(),
  -- columns
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now()
);

-- 2. Indexes (tenant_id leads every composite index)
create index <table>_tenant_created_idx on public.<table> (tenant_id, created_at desc);

-- 3. Triggers
create trigger <table>_set_updated_at before update on public.<table>
  for each row execute function app.set_updated_at();
create trigger <table>_audit after insert or update or delete on public.<table>
  for each row execute function app.audit_row();

-- 4. RLS (one policy per operation per role tier; using + with check on writes)
alter table public.<table> enable row level security;
create policy <table>_select_tenant on public.<table> for select to authenticated
  using (tenant_id = (select app.tenant_id()));
create policy <table>_insert_member on public.<table> for insert to authenticated
  with check (tenant_id = (select app.tenant_id()) and (select app.has_role('member')));
create policy <table>_update_admin on public.<table> for update to authenticated
  using (tenant_id = (select app.tenant_id()) and (select app.has_role('admin')))
  with check (tenant_id = (select app.tenant_id()) and (select app.has_role('admin')));
create policy <table>_delete_admin on public.<table> for delete to authenticated
  using (tenant_id = (select app.tenant_id()) and (select app.has_role('admin')));

commit;

-- rollback:
-- begin;
-- drop trigger if exists <table>_audit on public.<table>;
-- drop trigger if exists <table>_set_updated_at on public.<table>;
-- drop policy if exists <table>_delete_admin on public.<table>;
-- drop policy if exists <table>_update_admin on public.<table>;
-- drop policy if exists <table>_insert_member on public.<table>;
-- drop policy if exists <table>_select_tenant on public.<table>;
-- drop index if exists <table>_tenant_created_idx;
-- drop table if exists public.<table>;
-- commit;

-- rls-policies.sql — copy-paste snippets. Replace <table>, <col>. All assume app.* helpers from 0001_init.

-- ===== Helpers (once) =====
create schema if not exists app;
create or replace function app.tenant_id() returns uuid language sql stable as $$
  select nullif(((select auth.jwt()) -> 'app_metadata' ->> 'tenant_id'), '')::uuid $$;
create or replace function app.role() returns text language sql stable as $$
  select coalesce((select auth.jwt()) -> 'app_metadata' ->> 'role', 'member') $$;
create or replace function app.has_role(required text) returns boolean language sql stable as $$
  select array_position(array['viewer','member','admin','owner'], app.role())
      >= array_position(array['viewer','member','admin','owner'], required) $$;
create or replace function app.set_updated_at() returns trigger language plpgsql as $$
  begin new.updated_at = now(); return new; end $$;

-- ===== Pattern 1: tenant isolation =====
alter table public.<table> enable row level security;
create policy <table>_select_tenant on public.<table> for select to authenticated
  using (tenant_id = (select app.tenant_id()));
create policy <table>_insert_tenant on public.<table> for insert to authenticated
  with check (tenant_id = (select app.tenant_id()));
create policy <table>_update_tenant on public.<table> for update to authenticated
  using (tenant_id = (select app.tenant_id())) with check (tenant_id = (select app.tenant_id()));
create policy <table>_delete_tenant_admin on public.<table> for delete to authenticated
  using (tenant_id = (select app.tenant_id()) and (select app.has_role('admin')));

-- ===== Pattern 2: owner =====
create policy <table>_owner_all on public.<table> for all to authenticated
  using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));

-- ===== Pattern 2b: tenant + owner =====
create policy <table>_tenant_owner_write on public.<table> for update to authenticated
  using (tenant_id = (select app.tenant_id()) and created_by = (select auth.uid()))
  with check (tenant_id = (select app.tenant_id()) and created_by = (select auth.uid()));

-- ===== Pattern 3: role-based (own rows OR admin) =====
create policy <table>_update_own_or_admin on public.<table> for update to authenticated
  using (tenant_id = (select app.tenant_id()) and (created_by = (select auth.uid()) or (select app.has_role('admin'))))
  with check (tenant_id = (select app.tenant_id()) and (created_by = (select auth.uid()) or (select app.has_role('admin'))));

-- ===== Pattern 4: public read of published rows =====
create policy <table>_public_read on public.<table> for select to anon, authenticated
  using (status = 'published');
create policy <table>_admin_write on public.<table> for all to authenticated
  using ((select app.has_role('admin'))) with check ((select app.has_role('admin')));

-- ===== Pattern 5: storage bucket scoped by tenant folder =====
-- bucket 'tenant-files' private; object path '<tenant_id>/<file>'
create policy tenant_files_select on storage.objects for select to authenticated
  using (bucket_id = 'tenant-files' and (storage.foldername(name))[1] = (select app.tenant_id())::text);
create policy tenant_files_insert on storage.objects for insert to authenticated
  with check (bucket_id = 'tenant-files' and (storage.foldername(name))[1] = (select app.tenant_id())::text);

-- ===== Pattern 6: secure view over RLS table =====
create view public.<table>_public with (security_invoker = true) as
  select id, title, published_at from public.<table> where status = 'published';

-- ===== Pattern 7: security definer RPC with pinned search_path =====
create or replace function app.<fn>(p_arg uuid) returns setof public.<table>
language sql security definer set search_path = '' as $$
  select * from public.<table> where tenant_id = (select app.tenant_id()) and id = p_arg
$$;
revoke all on function app.<fn>(uuid) from public, anon;
grant execute on function app.<fn>(uuid) to authenticated;

-- ===== Audit of policies on a table =====
-- select policyname, cmd, roles, qual, with_check from pg_policies where tablename = '<table>';

skills/build/supabase-schema-rls/referen:
# RLS Integration Testing

Run against the local Supabase stack (`supabase start`), using the anon key with a signed JWT per persona. Every policy gets one positive and one negative test.

## Personas (from seed.sql)
| Persona | tenant_id | role | user id |
|---|---|---|---|
| A-owner | tenant A | owner | …000a1 |
| A-member | tenant A | member | …000a2 |
| A-viewer | tenant A | viewer | …000a3 |
| B-admin | tenant B | admin | …000b1 |
| anon | — | — | — |

## Harness (`tests/integration/rls/_client.ts`)
```ts
import { createClient } from "@supabase/supabase-js";
import { SignJWT } from "jose";

const url = process.env.NEXT_PUBLIC_SUPABASE_URL!;
const anon = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!;
const secret = new TextEncoder().encode(process.env.SUPABASE_JWT_SECRET!); // local default from `supabase status`

export async function asUser(p: { sub: string; tenant_id: string; role: string }) {
  const token = await new SignJWT({
    sub: p.sub, role: "authenticated", aud: "authenticated",
    app_metadata: { tenant_id: p.tenant_id, role: p.role },
  }).setProtectedHeader({ alg: "HS256" }).setIssuedAt().setExpirationTime("10m").sign(secret);
  return createClient(url, anon, { global: { headers: { Authorization: `Bearer ${token}` } } });
}
export const asAnon = () => createClient(url, anon);
```

## Test shape (`tests/integration/rls/invoices.test.ts`)
```ts
import { describe, it, expect } from "vitest";
import { asUser, asAnon } from "./_client";
import { seed } from "../../fixtures/seed-ids";

describe("invoices RLS", () => {
  it("A-member sees only tenant A rows", async () => {
    const db = await asUser(seed.aMember);
    const { data, error } = await db.from("invoices").select("tenant_id");
    expect(error).toBeNull();
    expect(new Set(data!.map(r => r.tenant_id))).toEqual(new Set([seed.tenantA]));
  });
  it("B-admin cannot read tenant A row by id", async () => {
    const db = await asUser(seed.bAdmin);
    const { data } = await db.from("invoices").select("id").eq("id", seed.invoiceA1);
    expect(data).toEqual([]);                         // RLS filters, no error
  });
  it("A-viewer cannot insert", async () => {
    const db = await asUser(seed.aViewer);
    const { error } = await db.from("invoices").insert({ number: "X-1", amount_cents: 100 });
    expect(error?.code).toBe("42501");                // new row violates row-level security policy
  });
  it("A-member cannot move a row to tenant B via update", async () => {
    const db = await asUser(seed.aMember);
    const { error } = await db.from("invoices").update({ tenant_id: seed.tenantB }).eq("id", seed.invoiceA1);
    expect(error?.code).toBe("42501");
  });
  it("anon sees nothing", async () => {
    const { data } = await asAnon().from("invoices").select("id");
    expect(data).toEqual([]);
  });
});
```

## Rules
| Rule | Why |
|---|---|
| Negative test asserts empty result for select, `42501` for writes | RLS filters reads silently and rejects writes loudly |
| Test `with check` by attempting to change `tenant_id`/`user_id` | catches the most common escalation |
| Test the lowest role that should be denied, not just anon | role boundaries are where mistakes live |
| Reset DB per test file (`supabase db reset` in `globalSetup`, or transaction rollback) | isolation |
| Run in CI `ci.yml` with `supabase start` service (or skip with a required local job) | policies regress silently otherwise |

## Vitest config
`tests/integration/**` runs with `environment: node`, `testTimeout: 20000`, sequential (`fileParallelism: false`) because they share one DB.

